  (2, 1, 'Nam', 'FPT University', 21.01665, 105.52472, 8, 2000000, 3000000, '2026-12', '0h - 1h', 5, 'Không', 'Thích thú cưng', 'Thỉnh thoảng nấu ăn', 'Yên tĩnh', 'Không dẫn bạn về', 'Học chiều', 'Chia đều tiền phòng & điện nước sòng phẳng', 'Thẳng thắn, cởi mở', 'Dân kỹ thuật, thích nấu ăn và nghe nhạc lofi. Tìm bạn nam tính tình dễ chịu, giữ vệ sinh chung tốt.'),
  (3, 1, 'Nam', 'FPT University', 21.01316, 105.51942, 8, 1600000, 2600000, '2026-11', 'Cú đêm', 5, 'Không hút thuốc', 'Không nuôi thú cưng', 'Ăn ngoài quán', 'Bình thường', 'Thỉnh thoảng cuối tuần', 'Linh hoạt', 'Dùng bao nhiêu tính bấy nhiêu minh bạch', 'Hòa đồng, vui vẻ', 'Học ngành Trí tuệ nhân tạo FPTU. Ban ngày đi học và lên lab, tối về yên tĩnh tự học. Tìm bạn cùng phòng tôn trọng không gian riêng tư.'),
  (4, 1, 'Nam', 'ĐH Công nghệ - ĐHQGHN', 21.02106, 105.52529, 8, 1400000, 2400000, '2026-11', '22h - 23h', 3, 'Không', 'Không nuôi thú cưng', 'Tự nấu ăn hàng ngày', 'Yên tĩnh', 'Không dẫn bạn về', 'Linh hoạt', 'Dùng bao nhiêu tính bấy nhiêu minh bạch', 'Thẳng thắn, cởi mở', 'Sinh viên ĐHQG Hòa Lạc, sống ngăn nắp, thích tự nấu ăn. Cần tìm 1 bạn nam share phòng ở khu Tân Xã hoặc Thạch Hòa để tiết kiệm chi phí.'),
